{
  "requirement_id": "REQ-005",
  "cases": [
    {
      "id": "TC-1",
      "title": "Allowed transitions from todo and in_progress",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with body {\"to\": \"in_progress\"} when task is in 'todo' status",
        "POST /api/tasks/{tid}/transition with body {\"to\": \"done\"} when task is in 'in_progress' status",
        "POST /api/tasks/{tid}/transition with body {\"to\": \"todo\"} when task is in 'in_progress' status"
      ],
      "expected": "允許從 todo 轉換至 in_progress, 允許從 in_progress 轉換至 done, 允許從 in_progress 轉換至 todo"
    },
    {
      "id": "TC-2",
      "title": "Forbidden transitions from done status",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with body {\"to\": \"todo\"} when task is in 'done' status",
        "POST /api/tasks/{tid}/transition with body {\"to\": \"in_progress\"} when task is in 'done' status"
      ],
      "expected": "done 為終態，任何從 done出發的流轉必須回傳 409 且任務狀態保持不變"
    },
    {
      "id": "TC-3",
      "title": "Forbidden other unlisted transitions and self-transitions",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with body {\"to\": \"done\"} when task is in 'todo' status",
        "POST /api/tasks/{tid}/transition with body {\"to\": \"todo\"} when task is in 'todo' status",
        "POST /api/tasks/{tid}/transition with body {\"to\": \"in_progress\"} when task is in 'in_progress' status",
        "POST /api/tasks/{tid}/transition with body {\"to\": \"done\"} when task is in 'done' status"
      ],
      "expected": "其他未列出的流轉（包含 todo 轉換至 done、或轉換至相同狀態）必須回傳 409"
    },
    {
      "id": "TC-4",
      "title": "Invalid state parameter in transition request",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with body {\"to\": \"invalid_status\"}"
      ],
      "expected": "當 to 參數不是合法的狀態時，必須回傳 422"
    }
  ]
}

